1	/**
2	 * PearlOS QA Screenshot Script
3	 *
4	 * Authenticates against the Dashboard login, waits for the ActiveJobsWidget,
5	 * captures a timestamped screenshot of the widget, and saves it to
6	 * /qa/screenshots/.
7	 *
8	 * Environment variables (read from .env.local by default):
9	 *   DASHBOARD_ADMIN_EMAIL    - login email
10	 *   DASHBOARD_ADMIN_PASSWORD - login password
11	 *   PEARLOS_URL              - base URL (default: http://localhost:3000)
12	 *   DISCORD_QA_WEBHOOK       - Discord webhook URL for screenshot delivery (optional)
13	 *
14	 * Usage:
15	 *   npx tsx scripts/qa-screenshot.ts
16	 */
17	
18	import { chromium, type Page } from 'playwright';
19	import * as fs from 'fs';
20	import * as path from 'path';
21	import * as dotenv from 'dotenv';
22	import FormData from 'form-data';
23	
24	// Load env
25	dotenv.config({ path: path.resolve(__dirname, '..', '.env.local') });
26	
27	const BASE_URL = process.env.PEARLOS_URL || 'http://localhost:3000';
28	const EMAIL = process.env.DASHBOARD_ADMIN_EMAIL;
29	const PASSWORD = process.env.DASHBOARD_ADMIN_PASSWORD;
30	const SCREENSHOTS_DIR = path.resolve(__dirname, '..', 'qa', 'screenshots');
31	const DISCORD_QA_WEBHOOK = process.env.DISCORD_QA_WEBHOOK;
32	
33	async function authenticate(page: Page): Promise<void> {
34	  if (!EMAIL || !PASSWORD) {
35	    throw new Error(
36	      'Missing DASHBOARD_ADMIN_EMAIL or DASHBOARD_ADMIN_PASSWORD in environment',
37	    );
38	  }
39	
40	  // Dashboard login lives at /dashboard/login
41	  await page.goto(`${BASE_URL}/dashboard/login`, { waitUntil: 'networkidle', timeout: 30_000 });
42	
43	  // The login form uses React Hook Form with placeholder-based inputs.
44	  // Target by placeholder text which is stable across renders.
45	  const emailInput = page.locator('input[placeholder="Username or Email"]');
46	  const passwordInput = page.locator('input[placeholder="****"]');
47	
48	  await emailInput.waitFor({ state: 'visible', timeout: 15_000 });
49	  await emailInput.fill(EMAIL);
50	  await passwordInput.fill(PASSWORD);
51	
52	  // Submit via the Sign In button
53	  await page.click('button[type="submit"]');
54	
55	  // Wait for navigation away from /login
56	  await page.waitForURL((url) => !url.pathname.includes('/login'), {
57	    timeout: 30_000,
58	  });
59	
60	  // Extra settle time for React hydration
61	  await page.waitForTimeout(3000);
62	}
63	
64	async function waitForActiveJobsWidget(page: Page): Promise<void> {
65	  // The ActiveJobsWidget injects a <style id="gohufont-active-jobs"> tag
66	  // when it mounts. We wait for that as a fingerprint.
67	  try {
68	    await page.waitForFunction(
69	      () => !!document.getElementById('gohufont-active-jobs'),
70	      { timeout: 20_000 },
71	    );
72	  } catch {
73	    console.warn(
74	      'ActiveJobsWidget font-face tag not found — widget may not be rendered. Continuing anyway.',
75	    );
76	  }
77	
78	  // Let animations settle
79	  await page.waitForTimeout(2000);
80	}
81	
82	function screenshotFilename(label: string): string {
83	  const ts = new Date().toISOString().replace(/[:.]/g, '-');
84	  const slug = label.replace(/[^a-z0-9]+/gi, '-').toLowerCase();
85	  return `${slug}-${ts}.png`;
86	}
87	
88	async function sendToDiscord(screenshotPaths: string[]): Promise<void> {
89	  if (!DISCORD_QA_WEBHOOK) {
90	    console.log('DISCORD_QA_WEBHOOK not set — skipping Discord delivery.');
91	    return;
92	  }
93	
94	  const form = new FormData();
95	
96	  const ts = new Date().toISOString();
97	  const embed = {
98	    title: 'QA Screenshot Report',
99	    description: `Captured ${screenshotPaths.length} screenshot(s) at ${ts}`,
100	    color: 0x00bfff,
101	    timestamp: ts,
102	    fields: screenshotPaths.map((p, i) => ({
103	      name: `Screenshot ${i + 1}`,
104	      value: path.basename(p),
105	    })),
106	  };
107	
108	  form.append(
109	    'payload_json',
110	    JSON.stringify({
111	      username: 'PearlOS QA Bot',
112	      embeds: [embed],
113	    }),
114	  ...

